INSERT INTO public.menu_products(id, cafe_id, category_id, name, description, price, image_url, sort_order, commerce_details, available)
SELECT p.id, meram.id, p.category_id, p.name, p.description, p.price, p.image_url, p.position, p.details, true
FROM meram CROSS JOIN products p JOIN public.menu_categories c ON c.id = p.category_id AND c.deleted_at IS NULL
WHERE c.cafe_id = meram.id
ON CONFLICT (id) DO NOTHING;
COMMIT;
